// @ts-check
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import mermaid from 'astro-mermaid';
import starlightLinksValidator from 'starlight-links-validator';

/** Sidebar group helper: one group per top-level docs directory, items autogenerated (Starlight >= 0.39 syntax). */
const group = (directory, label, ja, collapsed = false) => ({
	label,
	translations: { ja },
	collapsed,
	items: [{ autogenerate: { directory } }],
});

/** Keep raw Mermaid source out of the Pagefind search index (runs before Starlight's Pagefind hook). */
const pagefindIgnoreMermaid = () => ({
	name: 'pagefind-ignore-mermaid',
	hooks: {
		'astro:build:done': async ({ dir }) => {
			const { readdir, readFile, writeFile } = await import('node:fs/promises');
			const { fileURLToPath } = await import('node:url');
			const root = fileURLToPath(dir);
			for (const f of await readdir(root, { recursive: true })) {
				if (!f.endsWith('.html')) continue;
				const p = `${root}/${f}`;
				const html = await readFile(p, 'utf8');
				if (html.includes('<pre class="mermaid">')) {
					await writeFile(p, html.replaceAll('<pre class="mermaid">', '<pre class="mermaid" data-pagefind-ignore>'));
				}
			}
		},
	},
});

export default defineConfig({
	site: 'https://bmanterdev.github.io',
	base: '/github-cheatsheet',
	// Mermaid is large but lazy-loaded only on pages with diagrams.
	vite: { build: { chunkSizeWarningLimit: 4000 } },
	integrations: [
		pagefindIgnoreMermaid(),
		// astro-mermaid MUST be listed before Starlight.
		mermaid({
			theme: 'default',
			autoTheme: true,
			enableLog: false,
		}),
		starlight({
			title: {
				en: 'GitHub Expert Center Cheat Sheet',
				ja: 'GitHub エキスパートセンター チートシート',
			},
			description: 'Quick answers for the GitHub Universe Expert Center booth.',
			defaultLocale: 'root',
			locales: {
				root: { label: 'English', lang: 'en' },
				ja: { label: '日本語', lang: 'ja' },
			},
			social: [
				{ icon: 'github', label: 'GitHub', href: 'https://github.com/bmanterdev/github-cheatsheet' },
			],
			editLink: {
				baseUrl: 'https://github.com/bmanterdev/github-cheatsheet/edit/main/',
			},
			lastUpdated: true,
			customCss: ['./src/styles/custom.css'],
			plugins: [starlightLinksValidator()],
			sidebar: [
				group('start-here', 'Start here', 'はじめに'),
				group('actions', 'GitHub Actions', 'GitHub Actions'),
				group('copilot', 'GitHub Copilot', 'GitHub Copilot'),
				group('ghas', 'GitHub Advanced Security', 'GitHub Advanced Security'),
				group('migration', 'Migration', '移行', true),
				group('adoption', 'Adoption & Rollout', '導入と展開', true),
				group('administration', 'Administration', '管理', true),
				group('billing', 'Billing & Licensing', '請求とライセンス', true),
				group('codespaces', 'Codespaces', 'Codespaces', true),
				group('projects-issues', 'Projects & Issues', 'Projects & Issues', true),
				group('packages', 'Packages', 'Packages', true),
			],
		}),
	],
});
